/// Looks up one grid slot, bounds-checked against the table.
///
/// Every packed index is masked to its valid range at parse, so a
/// well-formed repack never fails here; a hand-built tensor with a
/// forged index is a length-style error, never a panic
/// (CONVENTIONS.md §1.5).
pub fn grid_slot(grid: &[u8], index: usize, what: &'static str) -> Result<u8, FormatError> {
    match grid.get(index) {
        Some(slot) => Ok(*slot),
        None => Err(FormatError::LengthMismatch {
            what,
            expected: (index + 1) as u64,
            got: grid.len() as u64,
        }),
    }
}

/// Looks up one signed grid slot (`IQ1_*`), bounds-checked.
pub fn grid_slot_signed(grid: &[i8], index: usize, what: &'static str) -> Result<i8, FormatError> {
    match grid.get(index) {
        Some(slot) => Ok(*slot),
        None => Err(FormatError::LengthMismatch {
            what,
            expected: (index + 1) as u64,
            got: grid.len() as u64,
        }),
    }
}
